// #6a993d78df85add81c766e3c — журнал доступа SA недоступен business/user; журнал другого бизнеса не виден.
// Кейс ACL-010. Только чтение — @prod-safe.
// Намеренно НЕ проверяется: business читает через REST audit_log СВОЕГО бизнеса — вопрос владельцу (session.json).
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';

const OTHER_BUSINESS = 'QA Test Business A';

test.describe('Журнал доступа — скрыт от business и user (#6a993d78df85add81c766e3c)', () => {
  test('business и user: /admin/access-log «אין לך הרשאה למסך הזה», RPC 403, журнал чужого бизнеса — 0 строк @desktop @prod-safe #6a993d78df85add81c766e3c', async ({ asUser }) => {
    const admin = await asUser('admin');
    const adminApi = await openWithApi(admin, '/admin/businesses');
    const bizRes = await adminApi.rpc('admin_list_businesses');
    expect(bizRes.status()).toBe(200);
    const other = ((await bizRes.json()) as { id: string; name: string }[]).find((b) => b.name === OTHER_BUSINESS);
    expect(other, `нет бизнеса «${OTHER_BUSINESS}»`).toBeTruthy();

    for (const role of ['business', 'user'] as const) {
      const page = await asUser(role);
      const api = await openWithApi(page, '/admin/access-log');
      await expect(page.getByRole('heading', { level: 1, name: 'אין לך הרשאה למסך הזה' }), role).toBeVisible();
      await expect(page.getByRole('heading', { level: 1, name: 'רישום גישה' })).toHaveCount(0);
      await expect(page.locator('#access-log-candidate')).toHaveCount(0);

      const rpc = await api.rpc('admin_list_access_log', {});
      expect(rpc.status(), `${role}: admin_list_access_log`).toBe(403);
      expect(await rpc.text()).toContain('forbidden');

      if (role === 'user') {
        const rows = await api.get('audit_log?select=id&limit=50');
        expect(rows.status()).toBe(200);
        expect(await rows.json(), 'user видит записи audit_log').toEqual([]);
      } else {
        // Источник: req. «משתמש עסקי אינו רואה את רישום הגישה של עסק אחר».
        const rows = await api.get(`audit_log?select=id&business_id=eq.${other!.id}`);
        expect(rows.status()).toBe(200);
        expect(await rows.json(), 'business видит журнал другого бизнеса').toEqual([]);
      }
    }
  });
});
